    hi: 'अपना मृदा स्वास्थ्य कार्ड या प्रयोगशाला रिपोर्ट अपलोड करें (PDF या छवि)। हम कभी भी मिट्टी का डेटा काल्पनिक नहीं बनाते।',
    te: 'మీ నేల ఆరోగ్య కార్డు లేదా ల్యాబ్ నివేదికను అప్‌లోడ్ చేయండి. మేము ఎప్పుడూ నకిలీ డేటాను సృష్టించము.',
    kn: 'ನಿಮ್ಮ ಮಣ್ಣು ಪರೀಕ್ಷಾ ವರದಿಯನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ. ನಾವು ಎಂದಿಗೂ ಸುಳ್ಳು ಡೇಟಾ ಸೃಷ್ಟಿಸುವುದಿಲ್ಲ.',
    ml: 'മണ്ണ് പരിശോധനാ കാർഡോ റിപ്പോർട്ടോ അപ്‌ലോഡ് ചെയ്യുക. ഞങ്ങൾ ഒരിക്കലും വ്യാജ വിവരങ്ങൾ നൽകില്ല.',
    mr: 'आपले माती परीक्षण पत्र किंवा लॅब अहवाल अपलोड करा. आम्ही खोटा डेटा कधीही दाखवत नाही.',
    bn: 'আপনার মৃত্তিকা স্বাস্থ্য কার্ড আপলোড করুন। আমরা কখনই ভুল তথ্য প্রদর্শন করি না।',
