/**
 * Universal translation resolver.
 * Handles English, Tamil (Standard vs Natural), Hindi, Telugu, Kannada, Malayalam, Marathi, Bengali.
 */
export function t(
  key: keyof typeof translations | string,
  language: SupportedLanguage = 'en',
  tamilDialect: TamilDialect = 'standard'
): string {
  const item = translations[key];
  if (!item) return String(key);

  if (language === 'ta') {
    return tamilDialect === 'natural'
      ? item['ta-natural'] || item['ta-standard'] || item['en'] || String(key)
      : item['ta-standard'] || item['en'] || String(key);
  }

  const localized = (item as any)[language];
  return localized || item['en'] || String(key);
}

/**
 * Crop catalog with multilingual labels and sensible defaults for India.
 */

/**
 * Localizes an alert severity ('info', 'attention', 'warning').
 */
export function localizeAlertSeverity(
  severity: string | undefined | null,
  translate: (k: string, d?: string) => string
): string {
  if (!severity) return translate('info', 'Info');
  const lower = severity.toLowerCase();
  if (lower === 'warning') return translate('warning', 'Warning');
  if (lower === 'attention') return translate('attention', 'Attention');
  return translate('info', 'Info');
}

/**
 * Localizes an alert type ('weather', 'field_risk', 'advisory', 'satellite', 'crop_stage', 'disease').
 */
export function localizeAlertType(
  type: string | undefined | null,
  translate: (k: string, d?: string) => string
): string {
  if (!type) return translate('alerts', 'Alert');
  switch (type.toLowerCase()) {
    case 'weather': return translate('weather', 'Weather');
    case 'field_risk': return translate('risks', 'Field Risk');
    case 'advisory': return translate('advisory', 'Advisory');
    case 'satellite': return translate('satellite', 'Satellite');
    case 'crop_stage': return translate('cropStage', 'Crop Stage');
    case 'disease': return translate('diseaseHistory', 'Disease');
    default: return type;
  }
}

/**
 * Localizes a risk severity enum ('LOW', 'MEDIUM', 'HIGH', 'CANNOT_DETERMINE').
 */
export function localizeRiskLevel(level: string | undefined | null, translate: (k: string, d?: string) => string): string {
  if (!level) return translate('levelCannotDetermine', 'Indeterminate');
  const upper = level.toUpperCase();
  if (upper === 'LOW') return translate('levelLow', 'Low');
  if (upper === 'MEDIUM') return translate('levelMedium', 'Moderate');
  if (upper === 'HIGH') return translate('levelHigh', 'High');
  return translate('levelCannotDetermine', 'Indeterminate');
}

/**
 * Localizes a confidence level ('Low', 'Moderate', 'High', 'None').
 */
export function localizeConfidenceLevel(confidence: string | undefined | null, translate: (k: string, d?: string) => string): string {
  if (!confidence) return translate('levelMedium', 'Moderate');
  const upper = confidence.toUpperCase();
  if (upper.includes('HIGH')) return translate('levelHigh', 'High');
  if (upper.includes('MOD') || upper.includes('MED')) return translate('levelMedium', 'Moderate');
  if (upper.includes('LOW')) return translate('levelLow', 'Low');
  return translate('levelCannotDetermine', 'Indeterminate');
}

/**
 * Localizes standard Indian crop names while preserving unlisted varieties.
 */
export function localizeCropName(crop: string | undefined | null, translate: (k: string, d?: string) => string): string {
  if (!crop) return '';
  const lower = crop.toLowerCase();
  if (lower.includes('rice') || lower.includes('paddy')) return translate('cropRice', crop);
  if (lower.includes('wheat')) return translate('cropWheat', crop);
  if (lower.includes('cotton')) return translate('cropCotton', crop);
  if (lower.includes('groundnut') || lower.includes('peanut')) return translate('cropGroundnut', crop);
  if (lower.includes('millet') || lower.includes('ragi') || lower.includes('bajra')) return translate('cropMillet', crop);
  if (lower.includes('sugarcane')) return translate('cropSugarcane', crop);
  if (lower.includes('maize') || lower.includes('corn')) return translate('cropMaize', crop);
  if (lower.includes('banana')) return translate('cropBanana', crop);
  if (lower.includes('chilli') || lower.includes('pepper')) return translate('cropChilli', crop);
  if (lower.includes('tomato')) return translate('cropTomato', crop);
  if (lower.includes('turmeric')) return translate('cropTurmeric', crop);
  return crop;
}

/**
 * Localizes data source strings for Farmer Alerts.
 */
export function localizeAlertSource(source: string | undefined | null, translate: (k: string, d?: string) => string): string {
  if (!source) return '';
  const lower = source.toLowerCase();
  if (lower.includes('open-meteo') || lower.includes('weather forecast')) {
    return translate('sourceWeatherForecast', 'Open-Meteo Weather Forecast');
  }
  if (lower.includes('field risk engine')) {
    return translate('sourceFieldRiskEngine', 'Field Risk Engine');
  }
  if (lower.includes('sentinel-2') || lower.includes('sentinel')) {
    return translate('sourceSentinel2', 'Sentinel-2 Open Data');
  }
  if (lower.includes('crop registry')) {
    return translate('sourceCropRegistry', 'Crop Registry Record');
  }
  if (lower.includes('foliar') || lower.includes('pathology')) {
    return translate('sourceFoliarInspection', 'Foliar Pathology Inspection');
  }
  if (lower.includes('advisory engine')) {
    return translate('sourceAdvisoryEngine', 'Advisory Engine');
  }
  return source;
}

/**
 * Localizes alert titles dynamically, preserving crop names and dynamic intervals.
 */
export function localizeAlertTitle(
  alert: { title?: string | null; type?: string | null; severity?: string | null } | string | undefined | null,
  translate: (k: string, d?: string) => string
): string {
  if (!alert) return '';
  const title = typeof alert === 'string' ? alert : (alert.title || '');
  if (!title) return '';

  const lower = title.toLowerCase();

  // Weather alerts
  if (lower.includes('heavy rain approaching')) {
    return translate('alertHeavyRainApproaching', 'Heavy Rain Approaching');
  }
  if (lower.includes('high rain probability')) {
    return translate('alertHighRainProb', 'High Rain Probability');
  }
  if (lower.includes('high wind speed')) {
    return translate('alertHighWind', 'High Wind Speed Advisory');
  }
  if (lower.includes('high temperature heat stress')) {
    return translate('alertHeatStress', 'High Temperature Heat Stress');
  }

  // Risk Engine heat stress titles
  if (lower.includes('heat stress alert') || lower.includes('heat stress threat')) {
    const cropMatch = title.match(/for\s+([A-Za-z0-9\s\(\)\/\-]+)/i);
    const crop = cropMatch ? localizeCropName(cropMatch[1].trim(), translate) : '';
    if (lower.includes('moderate')) {
      return translate('riskHeatStressMed', 'Moderate Heat Stress Alert for {crop}').replace('{crop}', crop || translate('crop', 'Crop'));
    }
    return translate('riskHeatStressHigh', 'Severe Heat Stress Threat for {crop}').replace('{crop}', crop || translate('crop', 'Crop'));
  }

  // Risk Engine rainfall & irrigation titles
  if (lower.includes('moderate precipitation')) {
    return translate('riskRainfallMed', 'Moderate Precipitation Expected');
  }
  if (lower.includes('waterlogging & leaching hazard')) {
    const cropMatch = title.match(/for\s+([A-Za-z0-9\s\(\)\/\-]+)/i);
    const crop = cropMatch ? localizeCropName(cropMatch[1].trim(), translate) : '';
    return translate('riskRainfallHigh', 'Waterlogging & Leaching Hazard for {crop}').replace('{crop}', crop || translate('crop', 'Crop'));
  }
  if (lower.includes('wasteful / detrimental immediate irrigation')) {
    return translate('riskIrrigationHigh', 'High Risk of Wasteful / Detrimental Immediate Irrigation');
  }
  if (lower.includes('irrigation timing uncertainty')) {
    return translate('riskIrrigationMed', 'Moderate Irrigation Timing Uncertainty');
  }
  if (lower.includes('favorable window for scheduled irrigation')) {
    return translate('riskIrrigationLow', 'Favorable Window for Scheduled Irrigation');
  }

  // Risk Engine water stress & vegetation titles
  if (lower.includes('water deficit') || lower.includes('canopy stress')) {
    const cropMatch = title.match(/in\s+([A-Za-z0-9\s\(\)\/\-]+)/i) || title.match(/for\s+([A-Za-z0-9\s\(\)\/\-]+)/i);
    const crop = cropMatch ? localizeCropName(cropMatch[1].trim(), translate) : '';
    return translate('riskWaterStressHigh', 'High Crop Water Deficit / Canopy Stress in {crop}').replace('{crop}', crop || translate('crop', 'Crop'));
  }
  if (lower.includes('potential incipient moisture stress')) {
    return translate('riskWaterStressMed', 'Potential Incipient Moisture Stress');
  }
  if (lower.includes('rapid decline in canopy vigour')) {
    return translate('riskVegetationHigh', 'Rapid Decline in Canopy Vigour');
  }
  if (lower.includes('vegetation vigour maintained')) {
    return translate('riskVegetationLow', 'Vegetation Vigour Maintained');
  }
  if (lower.includes('high agricultural risk')) {
    return translate('highFieldRisk', 'High Agricultural Risk');
  }
  if (lower.includes('moderate field risk')) {
    return translate('moderateFieldRisk', 'Moderate Field Risk');
  }

  // Satellite alerts
  if (lower.includes('new satellite observation')) {
    return translate('alertNewSatelliteObs', 'New Satellite Observation Available');
  }

  // Crop stage milestone alerts
  if (lower.includes('crop stage milestone')) {
    const daysMatch = title.match(/~(\d+)\s*Days/i) || title.match(/(\d+)\s*Days/i);
    const days = daysMatch ? daysMatch[1] : '';
    return translate('alertCropStageMilestone', 'Crop Stage Milestone (~{days} Days)').replace('{days}', days);
  }

  // Foliar screening disease alerts
  if (lower.includes('foliar screening alert:')) {
    const rawIssue = title.substring(title.indexOf(':') + 1).trim();
    let localizedIssue = rawIssue;
    if (rawIssue.toLowerCase().includes('screening inconclusive')) {
      localizedIssue = translate('screeningInconclusive', 'Screening Inconclusive');
    }
    return translate('alertFoliarScreening', 'Foliar Screening Alert: {issue}').replace('{issue}', localizedIssue);
  }

  return title;
}

/**
 * Localizes recommended action strings for Farmer Alerts.
 * Preserves custom farmer or localized non-English actions as-is.
 */
export function localizeAlertAction(
  alert: { action?: string | null; type?: string | null } | string | undefined | null,
  translate: (k: string, d?: string) => string
): string {
  if (!alert) return '';
  const action = typeof alert === 'string' ? alert : (alert.action || '');
  if (!action) return '';

  const lower = action.toLowerCase();

  if (lower.includes('postpone field irrigation, pesticide spraying')) {
    return translate('actionPostponeFieldCare', 'Postpone field irrigation, pesticide spraying, and fertilizer broadcast to prevent runoff and waterlogging.');
  }
  if (lower.includes('review recommended irrigation and canopy management actions')) {
    return translate('actionReviewIrrigationCanopy', 'Review recommended irrigation and canopy management actions.');
  }
  if (lower.includes('review risk mitigation steps and adjust field practices accordingly')) {
    return translate('actionReviewRiskMitigation', 'Review risk mitigation steps and adjust field practices accordingly.');
  }
  if (lower.includes('view field parcel imagery in the satellite section')) {
    return translate('actionViewSatellite', 'View field parcel imagery in the Satellite section.');
  }
  if (lower.includes('inspect crop tillering, vegetative growth, and weed management')) {
    return translate('actionCropStageInspect', 'Inspect crop tillering, vegetative growth, and weed management for this growth stage.');
  }
  if (lower.includes('suspend all chemical and foliar pesticide spraying')) {
    return translate('actionSuspendSpraying', 'Suspend all chemical and foliar pesticide spraying to prevent severe off-target drift.');
  }
  if (lower.includes('apply light frequent irrigation during cooler morning')) {
    return translate('actionLightFrequentIrrigation', 'Apply light frequent irrigation during cooler morning/evening hours and maintain soil mulching.');
  }
  if (lower.includes('take a sharper close-up photograph')) {
    return translate('actionSharperPhoto', 'Take a sharper close-up photograph under direct morning daylight.');
  }
  if (lower.includes('consult local krishi vigyan kendra')) {
    return translate('actionConsultKVK', 'Consult local Krishi Vigyan Kendra (KVK) for verified IPM recommendations.');
  }

  // Preserve custom non-English or specialized disease actions untouched
  return action;
}

/**
 * Localizes alert message body strings dynamically via regex tokenization.
 * Preserves field names, numbers, percentages, and dates verbatim.
 */
export function localizeAlertMessage(
  alert: { message?: string | null; type?: string | null; severity?: string | null; title?: string | null } | string | undefined | null,
  translate: (k: string, d?: string) => string
): string {
  if (!alert) return '';
  const msg = typeof alert === 'string' ? alert : (alert.message || '');
  if (!msg) return '';

  // 1. Weather Rain: "Numerical forecast indicates 55.0 mm rain (90% probability) for DEMO FIELD — TAMIL NADU."
  const weatherRainMatch = msg.match(/Numerical forecast indicates\s+([\d\.]+)\s*mm rain\s*\(([0-9]+)%\s*probability\)\s*for\s+(.+?)\.?$/i);
  if (weatherRainMatch) {
    const rain = weatherRainMatch[1];
    const prob = weatherRainMatch[2];
    const field = weatherRainMatch[3].replace(/\.$/, '');
    return translate('alertMsgWeatherRain', 'Numerical forecast indicates {rain} mm rain ({prob}% probability) for {field}.')
      .replace('{rain}', rain)
      .replace('{prob}', prob)
      .replace('{field}', field);
  }

  // 2. Weather Wind: "Wind speeds forecast at 22.5 km/h on DEMO FIELD — TAMIL NADU."
  const weatherWindMatch = msg.match(/Wind speeds forecast at\s+([\d\.]+)\s*km\/h\s*on\s+(.+?)\.?$/i);
  if (weatherWindMatch) {
    const speed = weatherWindMatch[1];
    const field = weatherWindMatch[2].replace(/\.$/, '');
    return translate('alertMsgWeatherWind', 'Wind speeds forecast at {speed} km/h on {field}.')
      .replace('{speed}', speed)
      .replace('{field}', field);
  }

  // 3. Weather Heat: "Forecast peak temperature of 38.5°C detected for DEMO FIELD — TAMIL NADU."
  const weatherHeatMatch = msg.match(/Forecast peak temperature of\s+([\d\.]+)\s*°C\s*detected for\s+(.+?)\.?$/i);
  if (weatherHeatMatch) {
    const temp = weatherHeatMatch[1];
    const field = weatherHeatMatch[2].replace(/\.$/, '');
    return translate('alertMsgWeatherHeat', 'Forecast peak temperature of {temp}°C detected for {field}.')
      .replace('{temp}', temp)
      .replace('{field}', field);
  }

  // 4. Satellite: "New Sentinel-2 satellite observation (2026-09-26) available for DEMO FIELD — TAMIL NADU (cloud cover: 5.4%)."
  const satMatch = msg.match(/New Sentinel-2 satellite observation\s*\(([^)]+)\)\s*available for\s+(.+?)\s*\(cloud cover:\s*([\d\.]+)%\)\.?/i);
  if (satMatch) {
    const date = satMatch[1];
    const field = satMatch[2];
    const cover = satMatch[3];
    return translate('alertMsgSatellite', 'New Sentinel-2 satellite observation ({date}) available for {field} (cloud cover: {cover}%).')
      .replace('{date}', date)
      .replace('{field}', field)
      .replace('{cover}', cover);
  }

  // 5. Crop Stage: "Your Rice (Paddy) on Main Parcel is approximately 31 days from recorded sowing date (27 Aug 2026)."
  const cropStageMatch = msg.match(/Your\s+(.+?)\s+on\s+(.+?)\s+is approximately\s+(\d+)\s+days from recorded sowing date\s*\(([^)]+)\)\.?/i);
  if (cropStageMatch) {
    const crop = cropStageMatch[1];
    const field = cropStageMatch[2];
    const days = cropStageMatch[3];
    const date = cropStageMatch[4];
    const localizedCrop = localizeCropName(crop, translate);
    return translate('alertMsgCropStage', 'Your {crop} on {field} is approximately {days} days from recorded sowing date ({date}).')
      .replace('{crop}', localizedCrop)
      .replace('{field}', field)
      .replace('{days}', days)
      .replace('{date}', date);
  }

  // 6. Foliar Disease Screening: "Visual screening for DEMO FIELD — TAMIL NADU identified Screening Inconclusive (Low confidence)."
  const diseaseMatch = msg.match(/Visual screening for\s+(.+?)\s+identified\s+(.+?)\s*\((.+?)\s+confidence\)\.?$/i);
  if (diseaseMatch) {
    const field = diseaseMatch[1];
    const rawIssue = diseaseMatch[2];
    const conf = diseaseMatch[3];
    let localizedIssue = rawIssue;
    if (rawIssue.toLowerCase().includes('screening inconclusive')) {
      localizedIssue = translate('screeningInconclusive', 'Screening Inconclusive');
    }
    const localizedConf = localizeConfidenceLevel(conf, translate);
    return translate('alertMsgDiseaseScreening', 'Visual screening for {field} identified {issue} ({conf} confidence).')
      .replace('{field}', field)
      .replace('{issue}', localizedIssue)
      .replace('{conf}', localizedConf);
  }

  // 7. Risk Engine evidence strings
  const rain48Match = msg.match(/Forecast indicates\s+([\d\.]+)\s*mm rain over 48 hours\s*\(max probability\s*(\d+)%\)\.?/i);
  if (rain48Match) {
    return translate('evidenceRainfallMed', 'Forecast indicates {rain} mm rain over 48 hours (max probability {prob}%).')
      .replace('{rain}', rain48Match[1])
      .replace('{prob}', rain48Match[2]);
  }

  const rainHighMatch = msg.match(/Next 48-hour cumulative precipitation forecast is\s+([\d\.]+)\s*mm\s*\(peak probability:\s*(\d+)%\)\.?/i);
  if (rainHighMatch) {
    return translate('evidenceRainfallHigh', 'Next 48-hour cumulative precipitation forecast is {rain} mm (peak probability: {prob}%).')
      .replace('{rain}', rainHighMatch[1])
      .replace('{prob}', rainHighMatch[2]);
  }

  const rainLowMatch = msg.match(/Negligible or light precipitation forecast\s*\(([\d\.]+)\s*mm over 48h\)\.?/i);
  if (rainLowMatch) {
    return translate('evidenceRainfallLow', 'Negligible or light precipitation forecast ({rain} mm over 48h).')
      .replace('{rain}', rainLowMatch[1]);
  }

  const irrigHighMatch = msg.match(/Imminent rainfall predicted\s*\(([\d\.]+)\s*mm,\s*(\d+)%\s*probability\)\.?\s*Irrigating today risks water wastage and root rot\.?/i);
  if (irrigHighMatch) {
    return translate('evidenceIrrigationHigh', 'Imminent rainfall predicted ({rain} mm, {prob}% probability). Irrigating today risks water wastage and root rot.')
      .replace('{rain}', irrigHighMatch[1])
      .replace('{prob}', irrigHighMatch[2]);
  }

  const irrigMedMatch = msg.match(/Precipitation probability is\s*(\d+)%\.?\s*Delaying non-critical irrigation by 24 hours is advisable\.?/i);
  if (irrigMedMatch) {
    return translate('evidenceIrrigationMed', 'Precipitation probability is {prob}%. Delaying non-critical irrigation by 24 hours is advisable.')
      .replace('{prob}', irrigMedMatch[1]);
  }

  const irrigLowMatch = msg.match(/Rain probability is low\s*\(([0-9]+)%\)\.?\s*Irrigation water will be efficiently utilized without displacement\.?/i);
  if (irrigLowMatch) {
    return translate('evidenceIrrigationLow', 'Rain probability is low ({prob}%). Irrigation water will be efficiently utilized without displacement.')
      .replace('{prob}', irrigLowMatch[1]);
  }

  const heatStressMedMatch = msg.match(/Current temperature is\s*([\d\.]+)°C\.?\s*Prolonged midday exposure may induce stomatal closure and pollen sterility\.?/i);
  if (heatStressMedMatch) {
    return translate('evidenceHeatStressMed', 'Current temperature is {temp}°C. Prolonged midday exposure may induce stomatal closure and pollen sterility.')
      .replace('{temp}', heatStressMedMatch[1]);
  }

  const heatStressHighMatch = msg.match(/Ambient temperature is\s*([\d\.]+)°C,\s*exceeding the physiological tolerance threshold\s*\((\d+)°C\)\s*for\s*(.+?)\.?$/i);
  if (heatStressHighMatch) {
    return translate('evidenceHeatStressHigh', 'Ambient temperature is {temp}°C, exceeding the physiological tolerance threshold ({threshold}°C) for {crop}.')
      .replace('{temp}', heatStressHighMatch[1])
      .replace('{threshold}', heatStressHighMatch[2])
      .replace('{crop}', localizeCropName(heatStressHighMatch[3].trim(), translate));
  }

  const heatStressLowMatch = msg.match(/Current temperature of\s*([\d\.]+)°C\s*is within standard physiological growing range\.?/i);
  if (heatStressLowMatch) {
    return translate('evidenceHeatStressLow', 'Current temperature of {temp}°C is within standard physiological growing range.')
      .replace('{temp}', heatStressLowMatch[1]);
  }

  const waterStressHighMatch = msg.match(/Sentinel-2 NDVI is depressed at\s*([\d\.]+)\s*and next 7-day precipitation forecast is only\s*([\d\.]+)\s*mm\.?/i);
  if (waterStressHighMatch) {
    return translate('evidenceWaterStressHigh', 'Sentinel-2 NDVI is depressed at {ndvi} and next 7-day precipitation forecast is only {rain} mm.')
      .replace('{ndvi}', waterStressHighMatch[1])
      .replace('{rain}', waterStressHighMatch[2]);
  }

  const waterStressMedMatch = msg.match(/NDVI is\s*([\d\.]+)\s*with modest forward precipitation\s*\(([\d\.]+)\s*mm\)\.?/i);
  if (waterStressMedMatch) {
    return translate('evidenceWaterStressMed', 'NDVI is {ndvi} with modest forward precipitation ({rain} mm).')
      .replace('{ndvi}', waterStressMedMatch[1])
      .replace('{rain}', waterStressMedMatch[2]);
  }

  const waterStressLowMatch = msg.match(/Vegetation index\s*\(NDVI:\s*([\d\.]+)\)\s*reflects healthy photosynthetic canopy activity\.?/i);
  if (waterStressLowMatch) {
    return translate('evidenceWaterStressLow', 'Vegetation index (NDVI: {ndvi}) reflects healthy photosynthetic canopy activity.')
      .replace('{ndvi}', waterStressLowMatch[1]);
  }

  const vegHighMatch = msg.match(/Observed NDVI has dropped to\s*([\d\.]+)\.?\s*Condition is classified as declining\.?/i);
  if (vegHighMatch) {
    return translate('evidenceVegetationHigh', 'Observed NDVI has dropped to {ndvi}. Condition is classified as declining.')
      .replace('{ndvi}', vegHighMatch[1])
      .replace('{condition}', 'declining');
  }

  const vegLowMatch = msg.match(/Vegetation index\s*\(NDVI\s*([\d\.]+)\)\s*indicates steady photosynthetic activity and canopy density\.?/i);
  if (vegLowMatch) {
    return translate('evidenceVegetationLow', 'Vegetation index (NDVI {ndvi}) indicates steady photosynthetic activity and canopy density.')
      .replace('{ndvi}', vegLowMatch[1]);
  }

  return msg;
}

/**
 * Maps a risk object from backend RiskEngine into fully localized title and evidence strings.
 */
export function localizeRisk(
  risk: { category?: string; level?: string; what_risk?: string; why_evidence?: string },
  translate: (k: string, d?: string) => string
): { what_risk: string; why_evidence: string } {
  if (!risk) {
    return {
      what_risk: translate('noElevatedHazards', 'No elevated agricultural hazards detected.'),
      why_evidence: translate('seasonalMarginsNotice', 'Weather, soil and thermal parameters remain within seasonal margins.')
    };
  }

  const cat = (risk.category || '').toUpperCase();
  const lvl = (risk.level || '').toUpperCase();
  const originalWhat = risk.what_risk || '';
  const originalWhy = risk.why_evidence || '';

  // Extract dynamic values using regex
  const tempMatch = originalWhy.match(/(\d+(?:\.\d+)?)\s*°C/);
  const temp = tempMatch ? tempMatch[1] : '';

  const thresholdMatch = originalWhy.match(/threshold\s*\((\d+(?:\.\d+)?)\s*°C\)/);
  const threshold = thresholdMatch ? thresholdMatch[1] : '35';

  const rainMatch = originalWhy.match(/(\d+(?:\.\d+)?)\s*mm/);
  const rain = rainMatch ? rainMatch[1] : '';

  const probMatch = originalWhy.match(/(\d+)%/);
  const prob = probMatch ? probMatch[1] : '';

  const ndviMatch = originalWhy.match(/NDVI(?:\s*is\s*|\s*:\s*|\s+)(\d+\.\d+)/i) || originalWhy.match(/(\d+\.\d+)/);
  const ndvi = ndviMatch ? ndviMatch[1] : '';

  const cropMatch = originalWhat.match(/for\s+([A-Za-z\s\(\)]+)/i) || originalWhat.match(/in\s+([A-Za-z\s\(\)]+)/i);
  const crop = cropMatch ? cropMatch[1].trim() : '';

  let localizedWhat = originalWhat;
  let localizedWhy = originalWhy;

  if (cat === 'HEAT_STRESS') {
    if (lvl === 'HIGH') {
      localizedWhat = translate('riskHeatStressHigh', 'Severe Heat Stress Threat for {crop}').replace('{crop}', crop || 'Crop');
      localizedWhy = translate('evidenceHeatStressHigh', 'Ambient temperature is {temp}°C, exceeding the physiological tolerance threshold ({threshold}°C) for {crop}.')
        .replace('{temp}', temp || '--')
        .replace('{threshold}', threshold)
        .replace('{crop}', crop || 'Crop');
    } else if (lvl === 'MEDIUM') {
      localizedWhat = translate('riskHeatStressMed', 'Moderate Heat Stress Alert for {crop}').replace('{crop}', crop || 'Crop');
      localizedWhy = translate('evidenceHeatStressMed', 'Current temperature is {temp}°C. Prolonged midday exposure may induce stomatal closure and pollen sterility.')
        .replace('{temp}', temp || '--');
    } else if (lvl === 'LOW') {
      localizedWhat = translate('riskHeatStressLow', 'Thermal Conditions Within Safe Agronomic Envelope');
      localizedWhy = translate('evidenceHeatStressLow', 'Current temperature of {temp}°C is within standard physiological growing range.')
        .replace('{temp}', temp || '--');
    } else {
      localizedWhat = translate('riskHeatStressIndeterminate', 'Heat Stress Status Indeterminate');
      localizedWhy = translate('evidenceHeatStressIndeterminate', 'Current temperature observation is unavailable from the meteorological provider.');
    }
  } else if (cat === 'HEAVY_RAINFALL') {
    if (lvl === 'HIGH') {
      localizedWhat = translate('riskRainfallHigh', 'Waterlogging & Leaching Hazard for {crop}').replace('{crop}', crop || 'Crop');
      localizedWhy = translate('evidenceRainfallHigh', 'Next 48-hour cumulative precipitation forecast is {rain} mm (peak probability: {prob}%).')
        .replace('{rain}', rain || '0')
        .replace('{prob}', prob || '0');
    } else if (lvl === 'MEDIUM') {
      localizedWhat = translate('riskRainfallMed', 'Moderate Precipitation Expected');
      localizedWhy = translate('evidenceRainfallMed', 'Forecast indicates {rain} mm rain over 48 hours (max probability {prob}%).')
        .replace('{rain}', rain || '0')
        .replace('{prob}', prob || '0');
    } else if (lvl === 'LOW') {
      localizedWhat = translate('riskRainfallLow', 'Minimal Heavy Rainfall Hazard');
      localizedWhy = translate('evidenceRainfallLow', 'Negligible or light precipitation forecast ({rain} mm over 48h).')
        .replace('{rain}', rain || '0');
    } else {
      localizedWhat = translate('riskRainfallIndeterminate', 'Precipitation Risk Indeterminate');
      localizedWhy = translate('evidenceRainfallIndeterminate', 'Multi-day quantitative precipitation forecast is currently unavailable.');
    }
  } else if (cat === 'DROUGHT_WATER_STRESS') {
    if (lvl === 'HIGH') {
      localizedWhat = translate('riskWaterStressHigh', 'High Crop Water Deficit / Canopy Stress in {crop}').replace('{crop}', crop || 'Crop');
      localizedWhy = translate('evidenceWaterStressHigh', 'Sentinel-2 NDVI is depressed at {ndvi} and next 7-day precipitation forecast is only {rain} mm.')
        .replace('{ndvi}', ndvi || '0.30')
        .replace('{rain}', rain || '0');
    } else if (lvl === 'MEDIUM') {
      localizedWhat = translate('riskWaterStressMed', 'Potential Incipient Moisture Stress');
      localizedWhy = translate('evidenceWaterStressMed', 'NDVI is {ndvi} with modest forward precipitation ({rain} mm).')
        .replace('{ndvi}', ndvi || '0.45')
        .replace('{rain}', rain || '0');
    } else if (lvl === 'LOW') {
      localizedWhat = translate('riskWaterStressLow', 'Adequate Canopy Hydration & Greenness');
      localizedWhy = translate('evidenceWaterStressLow', 'Vegetation index (NDVI: {ndvi}) reflects healthy photosynthetic canopy activity.')
        .replace('{ndvi}', ndvi || '0.65');
    } else {
      localizedWhat = translate('riskWaterStressIndeterminate', 'Crop Water Stress Cannot Be Conclusively Determined');
      localizedWhy = translate('evidenceWaterStressIndeterminate', 'Satellite optical observation unavailable. In-situ soil moisture sensors absent.');
    }
  } else if (cat === 'IRRIGATION_RISK') {
    if (lvl === 'HIGH') {
      localizedWhat = translate('riskIrrigationHigh', 'High Risk of Wasteful / Detrimental Immediate Irrigation');
      localizedWhy = translate('evidenceIrrigationHigh', 'Imminent rainfall predicted ({rain} mm, {prob}% probability). Irrigating today risks water wastage and root rot.')
        .replace('{rain}', rain || '10')
        .replace('{prob}', prob || '70');
    } else if (lvl === 'MEDIUM') {
      localizedWhat = translate('riskIrrigationMed', 'Moderate Irrigation Timing Uncertainty');
      localizedWhy = translate('evidenceIrrigationMed', 'Precipitation probability is {prob}%. Delaying non-critical irrigation by 24 hours is advisable.')
        .replace('{prob}', prob || '40');
    } else if (lvl === 'LOW') {
      localizedWhat = translate('riskIrrigationLow', 'Favorable Window for Scheduled Irrigation');
      localizedWhy = translate('evidenceIrrigationLow', 'Rain probability is low ({prob}%). Irrigation water will be efficiently utilized without displacement.')
        .replace('{prob}', prob || '10');
    } else {
      localizedWhat = translate('riskIrrigationIndeterminate', 'Irrigation Timing Risk Cannot Be Determined');
      localizedWhy = translate('evidenceIrrigationIndeterminate', 'Short-term precipitation probability telemetry is currently missing.');
    }
  } else if (cat === 'VEGETATION_DECLINE') {
    if (lvl === 'HIGH') {
      localizedWhat = translate('riskVegetationHigh', 'Rapid Decline in Canopy Vigour');
      localizedWhy = translate('evidenceVegetationHigh', 'Observed NDVI has dropped to {ndvi}. Condition is classified as declining.')
        .replace('{ndvi}', ndvi || '0.30')
        .replace('{condition}', 'declining');
    } else if (lvl === 'LOW') {
      localizedWhat = translate('riskVegetationLow', 'Vegetation Vigour Maintained');
      localizedWhy = translate('evidenceVegetationLow', 'Vegetation index (NDVI {ndvi}) indicates steady photosynthetic activity and canopy density.')
        .replace('{ndvi}', ndvi || '0.60');
    } else {
      localizedWhat = translate('riskVegetationIndeterminate', 'Vegetation Biomass Trend Indeterminate');
      localizedWhy = translate('evidenceVegetationIndeterminate', 'No recent cloud-free satellite observation. Raw STAC archive pending.');
    }
  }

  return { what_risk: localizedWhat, why_evidence: localizedWhy };
}

/**
 * Maps an advisory object from backend AdvisoryEngine into localized category, priority, title, and recommendation.
 */
export function localizeAdvisory(
  adv: { category?: string; priority?: string; title?: string; recommendation?: string },
  translate: (k: string, d?: string) => string
): { category: string; priority: string; title: string; recommendation: string } {
  if (!adv) {
    return {
      category: translate('advisoryIrrigation', 'IRRIGATION'),
      priority: translate('priorityLow', 'LOW'),
      title: translate('standardProtocolActive', 'Standard seasonal management protocol active.'),
      recommendation: translate('standardProtocolDesc', 'Maintain regular irrigation intervals and inspect leaves for emerging foliar lesions or pest egg clutches.')
    };
  }

  const cat = (adv.category || '').toUpperCase();
  const prio = (adv.priority || '').toUpperCase();
  const title = adv.title || '';
  const rec = adv.recommendation || '';

  // Localize Category
  let localizedCategory = adv.category || 'ADVISORY';
  if (cat === 'IRRIGATION') localizedCategory = translate('advisoryIrrigation', 'IRRIGATION');
  else if (cat === 'SPRAYING') localizedCategory = translate('advisorySpraying', 'SPRAYING');
  else if (cat === 'MONITORING') localizedCategory = translate('advisoryMonitoring', 'MONITORING');
  else if (cat === 'FERTILIZATION') localizedCategory = translate('advisoryFertilization', 'FERTILIZATION');

  // Localize Priority
  let localizedPriority = adv.priority || 'NORMAL';
  if (prio === 'HIGH') localizedPriority = translate('priorityHigh', 'HIGH');
  else if (prio === 'MEDIUM') localizedPriority = translate('priorityMedium', 'MEDIUM');
  else if (prio === 'LOW') localizedPriority = translate('priorityLow', 'LOW');

  // Dynamic extractions
  const rainMatch = rec.match(/(\d+(?:\.\d+)?)\s*mm/);
  const rain = rainMatch ? rainMatch[1] : '';

  const probMatch = rec.match(/(\d+)%/);
  const prob = probMatch ? probMatch[1] : '';

  const speedMatch = rec.match(/(\d+(?:\.\d+)?)\s*km\/h/);
  const speed = speedMatch ? speedMatch[1] : '';

  const tempMatch = rec.match(/(\d+(?:\.\d+)?)\s*°C/);
  const temp = tempMatch ? tempMatch[1] : '';

  const ocMatch = rec.match(/(\d+(?:\.\d+)?)\s*%/);
  const oc = ocMatch ? ocMatch[1] : '';

  const cropMatch = rec.match(/for\s+([A-Za-z\s\(\)]+)/i);
  const crop = cropMatch ? cropMatch[1].trim() : 'Crop';

  let localizedTitle = title;
  let localizedRec = rec;

  if (title.toLowerCase().includes('postpone irrigation')) {
    localizedTitle = translate('titlePostponeIrrigation', 'Postpone Irrigation Due to Expected Rain');
    localizedRec = translate('recPostponeIrrigation', 'Postpone field irrigation for the next 24-48 hours. Numerical forecast indicates {rain} mm rain with {prob}% probability. Delaying irrigation prevents waterlogging, root asphyxiation, and energy waste.')
      .replace('{rain}', rain || '15')
      .replace('{prob}', prob || '60');
  } else if (title.toLowerCase().includes('light') && title.toLowerCase().includes('irrigation')) {
    localizedTitle = translate('titleLightIrrigation', 'Light / Controlled Irrigation Recommended');
    localizedRec = translate('recLightIrrigation', 'Maintain moderate soil moisture. Marginal chance of rain exists; avoid deep canal inundation to allow capacity for possible showers.');
  } else if (title.toLowerCase().includes('proceed with standard') || (title.toLowerCase().includes('standard') && title.toLowerCase().includes('irrigation'))) {
    localizedTitle = translate('titleStandardIrrigation', 'Proceed With Standard Crop Irrigation Cycle');
    localizedRec = translate('recStandardIrrigation', 'Low probability of rain ({prob}%). Proceed with standard irrigation schedule for {crop}, preferably during early morning or evening hours to minimize evapotranspiration losses.')
      .replace('{prob}', prob || '10')
      .replace('{crop}', crop);
  } else if (title.toLowerCase().includes('suspend chemical spraying')) {
    localizedTitle = translate('titleSuspendSpraying', 'Suspend Chemical Spraying (Drift Hazard)');
    localizedRec = translate('recSuspendSpraying', 'Wind speed is currently {speed} km/h, which exceeds the safe threshold (15 km/h). Suspend all pesticide/herbicide spraying to avoid off-target drift, chemical wastage, and environmental contamination.')
      .replace('{speed}', speed || '16');
  } else if (title.toLowerCase().includes('avoid foliar spraying')) {
    localizedTitle = translate('titleAvoidFoliar', 'Avoid Foliar Spraying (Wash-off Risk)');
    localizedRec = translate('recAvoidFoliar', 'Rain probability is {prob}%. Avoid applying foliar fertilizers or systemic fungicides, as rainfall within 4 hours will wash off active ingredients.')
      .replace('{prob}', prob || '50');
  } else if (title.toLowerCase().includes('safe window for agro-chemical')) {
    localizedTitle = translate('titleSafeSpraying', 'Safe Window for Agro-Chemical / Foliar Applications');
    localizedRec = translate('recSafeSpraying', 'Wind speeds are calm ({speed} km/h) and rainfall probability is low ({prob}%). Suitable window for foliar nourishment or bio-pesticide application.')
      .replace('{speed}', speed || '8')
      .replace('{prob}', prob || '10');
  } else if (title.toLowerCase().includes('spray conditions indeterminate')) {
    localizedTitle = translate('titleSprayIndeterminate', 'Spray Conditions Indeterminate');
    localizedRec = translate('recSprayIndeterminate', 'Wind speed data unavailable. Test localized wind with a windsock or leaf drift before applying any foliar spray.');
  } else if (title.toLowerCase().includes('heat stress mitigation')) {
    localizedTitle = translate('titleHeatMitigation', 'Heat Stress Mitigation Required');
    localizedRec = translate('recHeatMitigation', 'Extreme daytime temperature ({temp}°C) detected. Apply light frequent sprinkler irrigations during peak afternoon hours to suppress canopy temperature. Maintain organic mulch on bed ridges.')
      .replace('{temp}', temp || '37');
  } else if (title.toLowerCase().includes('soil health & nutrient')) {
    localizedTitle = translate('titleSoilHealthBalancing', 'Soil Health & Nutrient Balancing');
    if (rec.toLowerCase().includes('low organic carbon')) {
      localizedRec = translate('recLowOC', 'Soil test indicates low organic carbon ({oc}%). Apply 5-8 tonnes/ha farmyard manure (FYM) or vermicompost before next sowing to restore microbial biomass and cation exchange capacity.')
        .replace('{oc}', oc || '0.40');
    } else {
      localizedRec = translate('recSatisfactoryOC', 'Soil organic carbon is satisfactory ({oc}%). Continue crop residue incorporation and balanced NPK dosing as per soil health test.')
        .replace('{oc}', oc || '0.65');
    }
  } else if (title.toLowerCase().includes('soil nutrient advisory')) {
    localizedTitle = translate('titleSoilNutrientGeneral', 'Soil Nutrient Advisory (General Basal Guidance)');
    localizedRec = translate('recGeneralBasal', 'No lab soil test on record. Apply standardized state university basal NPK package for your district. We strongly recommend conducting a laboratory soil test at your nearest KVK or Soil Testing Lab to avoid wasteful fertilizer application.');
  }

  return {
    category: localizedCategory,
    priority: localizedPriority,
    title: localizedTitle,
    recommendation: localizedRec
  };
}

/**
 * Localizes factor items displayed under advisories.
 */
export function localizeFactor(factor: string, translate: (k: string, d?: string) => string): string {
  if (!factor) return '';
  if (factor.includes('Forecast Precipitation')) {
    const val = factor.split(':')[1] || '';
    return translate('factorForecastPrecip', 'Forecast Precipitation: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Low Rain Probability')) {
    const val = factor.split(':')[1] || '';
    return translate('factorLowRainProb', 'Low Rain Probability: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Rain Probability')) {
    const val = factor.split(':')[1] || '';
    return translate('factorRainProb', 'Rain Probability: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Favorable Evaporation Window')) {
    return translate('factorFavorableEvapWindow', 'Favorable Evaporation Window');
  }
  if (factor.includes('Wind Speed')) {
    const val = factor.split(':')[1] || '';
    return translate('factorWindSpeed', 'Wind Speed: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('High Ambient Temperature')) {
    const val = factor.split(':')[1] || '';
    return translate('factorHighAmbientTemp', 'High Ambient Temperature: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Organic Carbon')) {
    const val = factor.split(':')[1] || '';
    return translate('factorOrganicCarbon', 'Organic Carbon: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Data Type')) {
    const val = factor.split(':')[1] || '';
    return translate('factorDataType', 'Data Type: {val}').replace('{val}', val.trim());
  }
  if (factor.includes('Soil Data: UNAVAILABLE') || factor.includes('Generic regional profile applied')) {
    return translate('factorSoilUnavailable', 'Soil Data: UNAVAILABLE (Generic regional profile applied)');
  }
  return factor;
}

